\label{CS:manifold}
	For the the network $\mathcal{G}=(\mathcal{V},\mathcal{E})$, consider the partition $\mathcal{C}:=\{\mathcal{C}_1,\mathcal{C}_2,\dots,\mathcal{C}_r\}$, where $\mathcal{C}_k\subset \mathcal{V}$, $\mathcal{C}_k \cap  \mathcal{C}_\ell =\emptyset$ for any $k\neq \ell$, and $\cup_{k=1}^r \mathcal{C}_k=\mathcal{V}$. The \textit{cluster synchronization manifold} associated with the partition $\mathcal{C}$ is defined as
	\begin{equation*}
	\mathcal{M}:= \{\theta \in \mathbb{T}^n: \theta_i=\theta_j, \forall i,j \in \mathcal{C}_k,  k= 1,\dots,r\}.\hspace{12pt}\null \hfill\ensuremath{\triangle}
\end{equation*}

\label{general}
	Assume that $\bar J={\rm blkdiag}(\bar J^{(1)},\dots,\bar J^{(r)})$ in Eq.~\eqref{J-bar} is Hurwitz. Let $\bar X_k$ be the solution to the Lyapunov equation 
	\begin{align}\label{Ly:controlled}
		{(\bar J^{(k)})^\top \bar X_k+\bar X_k^\top \bar J^{(k)}=-I}.
	\end{align}
	Define the matrix $S=[s_{k \ell}]_{r\times r} $ with
	\begin{align}\label{matrix:S}
	s_{k\ell}=\Big\{\begin{matrix*}[l]
		\lambda_{\max}^{-1}(\bar X_k)-\bar\gamma_{k k} , &\text{ if }k=\ell,\\
		s_{k\ell}= -\bar \gamma_{k \ell}, &\text{ if }k \neq\ell.
	\end{matrix*}
	\end{align}
	If $S$ is an $M$-matrix, then  there exists $\varepsilon^*>0$ such that, for any $\varepsilon<\varepsilon^*$:

	(i) the equilibrium $x=0$ of the system \eqref{compact_form} is exponentially stable uniformly in $y$; 

	(ii) the cluster synchronization manifold $\mathcal{M}$ of the system \eqref{model:controlled} is exponentially stable.

For a stable linear system $\dot x=Ax$, previous studies propose that $\lambda_{\max}(X)$, where $X$ is the solution to the Lyapunov equation $A^\top X+X A=-2I$, can measure the robustness of this system \cite{PRV-TM:80,YR:85}. 
	In our case, from \eqref{linearized}, the uncontrolled intra-dynamics around the manifold $\mathcal{M}$ are described by 
	\begin{align}\label{uncontrolled}
		&\dot x_k=J^{(k)} x_k+f^{(k)}_{\rm inter}(x,y),&k=1,\dots,r,
	\end{align}
	where $J^{(k)}$ is stable and $f^{(k)}_{\rm inter}(x,y)$ is taken as the perturbation. Here, $x_k=0$ means synchronization of the oscillators in the $k$th cluster. Let $X_k$ be the solution to 
	\begin{align}\label{Ly:uncontrolled}
		\scalebox{0.85}{\mbox{\ensuremath{\displaystyle ( J^{(k)})^\top X_k+X_k^\top  J^{(k)}=-I}}}.
	\end{align}
Likewise, one can use $\lambda^{-1}_{\max}(X_k)$ to measure the robustness of synchronization in the $k$th cluster. If the intra-cluster synchronization is sufficiently robust (i.e., large $\lambda^{-1}_{\max}(X_k)$'s) to dominate the perturbations resulted from inter-cluster connections, the cluster synchronization is stable. A sufficient condition is constructed in \cite[Th. 3.2]{TM-GB-DSB-FP:18}. By contrast, if $\lambda_{\max}(X_k)$'s are not large enough, the cluster synchronization can lose its stability. Yet, the robustness of the intra-cluster synchronization can be reshaped by introducing vibrations to the local network connections. The new robustness is instead measured by $\lambda^{-1}_{\max}( \bar X_k)$, where $\bar X_k$ is the solution to Eq.~\eqref{Ly:controlled}.  \null \hfill\ensuremath{\triangle}

We restrict our attention to only one cluster in this example. Specifically, consider that $J^{(k)}$ in \eqref{uncontrolled} is 
	\begin{align*}
		\scalebox{0.85}{\mbox{\ensuremath{\displaystyle J^{(k)}=\begin{bmatrix}
		-1& 4\\0 &-2
	\end{bmatrix}}}}. 
\end{align*}
Suppose that there is a vibrational control $U^{(k)}(t)$ to the $k$th cluster that results in the state transition matrix 
	\begin{align*}
		{\Phi^{(k)}(t,t_0)=\begin{bmatrix}
				1&0\\
				\cos(t_0)-\cos(t)&1
		\end{bmatrix}}.
	\end{align*} It can be calculated that 
\begin{align*}
	\scalebox{0.9}{\mbox{\ensuremath{\displaystyle \bar J^{(k)} =\frac{1}{2\pi}\int_{0}^{2 \pi} \big(\Phi^{(k)}(t,t_0)\big)^{-1} J^{(k)} \Phi^{(k)}(t,t_0)dt=\begin{bmatrix}
		-1& 4\\-2 &-2
	\end{bmatrix}}}}.
\end{align*}
Solving the equations \eqref{Ly:controlled} and \eqref{Ly:uncontrolled}, one can obtain $\lambda^{-1}_{\max}( X_k)\approx 0.52$ and $\lambda^{-1}_{\max}(\bar X_k)=2$, which means that the synchronization in this cluster becomes more robust due to the vibrational control. \null \hfill\ensuremath{\triangle}

\label{incidence:transfer}
	For the incidence matrices $B$ and $\hat B$, there exists $R={ 
		\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\scriptsize}{8}{9pt}}{8}{9pt}}{8}{9pt}}{8}{9pt}}{8}{9pt}}{8}{9pt}}{8}{9pt}\arraycolsep=0.4\arraycolsep\ensuremath{\begin{bmatrix}
		R_1&0\\
		R_2&R_3\end{bmatrix}}}$ such that $B^\top =R\hat B^\top$,  where 
	\begin{align*}
		\scalebox{0.85}{\mbox{\ensuremath{\displaystyle R_1= {\rm blkdiag}\big((B^{(1)}_{{\rm intra}})^\top ((\hat B^{(1)}_{{\rm intra}})^\top)^\dagger,\dots,(B^{(r)}_{{\rm intra}})^\top ((\hat B^{(r)}_{{\rm intra}})^\top)^\dagger\big),}}}
	\end{align*}
	and ${ 
		\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}\arraycolsep=0.9\arraycolsep\ensuremath{\begin{matrix}R_2=B_{\rm inter}^\top (\hat B_{\rm intra} ^\top P_{\rm inter})^\dagger\end{matrix}}}$,
	${ 
		\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}\arraycolsep=0.9\arraycolsep\ensuremath{\begin{matrix}R_3= B_{\rm inter}^\top (\hat B_{\rm inter} P_{\rm intra})^\dagger\end{matrix}}}$
with ${ 
		\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}\arraycolsep=0.9\arraycolsep\ensuremath{\begin{matrix}P_{\rm intra}=I_n-\hat B_{\rm intra} \hat B_{\rm intra}^\dagger\end{matrix}}}$ and ${ 
		\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\@setfontsize{\small}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}}{10}{12pt}\arraycolsep=0.9\arraycolsep\ensuremath{\begin{matrix}P_{\rm inter}=I_n-\hat B_{\rm inter} \hat B_{\rm inter}^\dagger\end{matrix}}}$. \null \hfill\ensuremath{\triangle}

The expressions of $R_2$ and $R_3$ follow from \cite{KR-IH:2021}. Recall that ${B_{\rm intra}={\rm blkdiag}( B_{{\rm intra}}^{(1)},\dots, B_{{\rm intra}}^{(r))}}$and ${\hat B_{\rm intra}={\rm blkdiag}(\hat B^{(1)}_{{\rm intra}},\dots,\hat B^{(r)}_{{\rm intra}})}$. Since ${(B^{(k)}_{{\rm intra}})^\top }$ has full row rank, we have 
	\begin{align*}
		(B^{(k)}_{{\rm intra}})^\top = (B^{(k)}_{{\rm intra}})^\top ((\hat B^{(k)}_{{\rm intra}})^\top)^\dagger(\hat B^{(k)}_{{\rm intra}})^\top,
	\end{align*}
	which completes the proof.

\label{lemma:bound:pert}
	There exist some constants $\bar \gamma_{k\ell}>0$, $k,\ell=1,\dots,r$, such that, for any $k$, it holds that 
	\begin{align*}
	\|\Phi^{-1} f^{(k)}_{\rm inter}( \Phi z, y)\|\le \sum\nolimits_{\ell=1}^{r}\bar \gamma_{k\ell} \|z_\ell\|.\hspace{20pt}\null \hfill\ensuremath{\triangle}
	\end{align*}
